#include <SDL2/SDL.h>
#include <SDL2/SDL_image.h>
#include <stdio.h>
#include <stdlib.h>

#define SCREEN_WIDTH 800
#define SCREEN_HEIGHT 600
#define FOOD_WIDTH 20
#define FOOD_HEIGHT 20
#define SNAKE_WIDTH 20
#define SNAKE_HEIGHT 20

enum Direction {
    UP,
    DOWN,
    LEFT,
    RIGHT,
};

struct Snake {
    int x, y;
    enum Direction dir;
    int len;
    int *body;
};

struct Food {
    int x, y;
};

// Function prototypes
